<template>
  <div class="game-board">
    <div class="card-stack" v-for="(stack, index) in cardStacks" :key="index">
      <Card v-for="(card, cardIndex) in stack" :key="cardIndex" :value="card.value" :isFaceUp="card.isFaceUp" />
    </div>
  </div>
</template>

<script>
import Card from '@/components/Card.vue';

export default {
  name: 'GameBoard',
  components: {
    Card,
  },
  data() {
    return {
      cardStacks: [
        // 初始卡牌布局：前4叠6张，后6叠5张
        ...Array(4).fill(
          Array(6).fill({ value: 'A', isFaceUp: false }).map((card, i) =>
            i === 0 ? { ...card, isFaceUp: true } : card
          )
        ),
        ...Array(6).fill(
          Array(5).fill({ value: 'A', isFaceUp: false }).map((card, i) =>
            i === 0 ? { ...card, isFaceUp: true } : card
          )
        ),
      ],
    };
  },
};
</script>

<style scoped>
.game-board {
  display: flex;
  justify-content: space-around;
  flex-wrap: wrap;
  padding: 20px;
  flex-grow: 1;
  background-color: #007700;
}

.card-stack {
  display: flex;
  flex-direction: column;
  gap: 5px;
  margin: 5px;
}
</style>